import {validProductVideo,orderedProductMedia,mountMediaEditor} from './product-media.js';
import {marketplaceCatalog} from './catalog.js';
import { sellerContext, readMarketplace } from './marketplace-settings.js';
import { TYPE_LABELS, makeVariants, combinations, validateProductConfig } from './product-types.js';
const editorKey='marketplace.product-drafts.v1';
const editorEscape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaultComponentPool=[{id:0,name:'Poltrona de madeira com estofado',type:'simple',store:0,sku:'ML-0',stock:8,priceCents:68990},{id:7,name:'Luminária de mesa',type:'variable',store:0,priceCents:15990,attributes:[{name:'Voltagem',values:['127 V','220 V']}],variants:makeVariants(7,[{name:'Voltagem',values:['127 V','220 V']}],159.9)},{id:9,name:'Cadeira contemporânea',type:'simple',store:0,sku:'ML-9',stock:8,priceCents:34990}];
let draftMemory=[];
export function readProductDrafts(){try{const data=JSON.parse(localStorage.getItem(editorKey)||'[]');return Array.isArray(data)?data:draftMemory}catch{return draftMemory}}
function saveProductDraft(draft){draftMemory=readProductDrafts().filter(p=>p.id!==draft.id).concat(draft);try{localStorage.setItem(editorKey,JSON.stringify(draftMemory));return true}catch{return false}}
export function productEditorMarkup(){return `<section class="portal-panel"><div class="editor-heading"><div><span class="eyebrow">CATÁLOGO · ${editorEscape(readMarketplace().stores.find(s=>s.id===sellerContext())?.name)}</span><h2>Cadastro e edição de produto</h2><a class="text-link" href="#seller/produtos">← Voltar aos produtos</a><p>Cadastre produtos simples, variações, kits e arquivos digitais.</p></div></div><button class="btn secondary" type="button" id="new-product">Novo produto</button><div class="type-selector">${Object.entries(TYPE_LABELS).map(([id,label])=>`<button type="button" data-editor-type="${id}" aria-pressed="${id==='simple'}"><b>${label}</b><span>${{simple:'Uma oferta, sem escolhas',variable:'Atributos e combinações',kit:'Fechado ou aberto',virtual:'Arquivos para download'}[id]}</span></button>`).join('')}</div><form id="typed-product-form"><div class="form-two"><label class="field-label">Nome do produto<input class="panel-input" name="name" required maxlength="120" placeholder="Nome que aparece para o comprador"></label><label class="field-label">Preço base (R$)<input class="panel-input" name="price" type="number" min="0.01" step="0.01" value="99.90" required></label></div><label class="field-label">Descrição<textarea class="panel-input" name="description" maxlength="3000"></textarea></label><label class="field-label">Categoria<input class="panel-input" name="category" required></label><div hidden><input name="image"><input name="videoUrl"><select name="firstMedia"><option value="image">Imagem</option><option value="video">Vídeo</option></select></div><section id="ordered-media-editor"></section><div id="type-editor-fields"></div><div class="editor-actions"><button class="btn" type="submit">Salvar rascunho</button><button class="btn secondary" type="submit" name="submitReview" value="yes">Enviar para aprovação</button></div><p id="editor-feedback" role="status"></p></form><div class="seller-note">Protótipo local. Rascunhos e metadados ficam neste navegador quando o armazenamento está disponível. Arquivos não são enviados. Conteúdo exige aprovação; cursos e aulas em vídeo não são permitidos.</div></section><div id="product-drafts-list" hidden></div>`}
export function mountProductEditor(editId=null){const componentPool=sellerProducts().filter(p=>p.store===sellerContext()&&['simple','variable'].includes(p.type));const f=document.querySelector('#typed-product-form');if(!f)return;let type='simple',id=Date.now(),attributes=[],variants=[],digital=null,original=null;
  const fields=document.querySelector('#type-editor-fields'),feedback=document.querySelector('#editor-feedback');const mediaEditor=mountMediaEditor(document.querySelector('#ordered-media-editor')); 
  const attrRows=()=>attributes.map((a,i)=>`<div class="attribute-editor-row"><label class="field-label">Nome do atributo<input class="panel-input" data-attr-name="${i}" value="${editorEscape(a.name)}" maxlength="40" placeholder="Cor, tamanho, voltagem..."></label><label class="field-label">Opções separadas por vírgula<input class="panel-input" data-attr-values="${i}" value="${editorEscape(a.values.join(', '))}" maxlength="250" placeholder="Preto, Branco"></label><button class="text-link" type="button" data-remove-attr="${i}">Remover</button></div>`).join('');
  const rows=()=>`<div class="portal-table"><table><thead><tr><th>Combinação</th><th>SKU</th><th>Preço (R$)</th><th>Estoque</th><th>Ativa</th></tr></thead><tbody>${variants.map((v,i)=>`<tr><td>${Object.entries(v.attributes).map(([k,val])=>editorEscape(k)+': '+editorEscape(val)).join(' · ')}</td><td><input class="panel-input" data-variant="${i}" data-field="sku" value="${editorEscape(v.sku)}" required></td><td><input class="panel-input" data-variant="${i}" data-field="priceCents" type="number" min="0.01" step="0.01" value="${v.priceCents/100}" required></td><td><input class="panel-input" data-variant="${i}" data-field="stock" type="number" min="0" step="1" value="${v.stock}" required></td><td><input type="checkbox" data-variant="${i}" data-field="active" ${v.active?'checked':''} aria-label="Ativar combinação ${i+1}"></td></tr>`).join('')}</tbody></table></div>`;
  function draw(config={}){document.querySelectorAll('[data-editor-type]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.editorType===type)));f.elements.price.required=type!=='kit';f.elements.price.closest('label').hidden=type==='kit';
    if(type==='simple')fields.innerHTML=`<div class="form-two"><label class="field-label">SKU<input class="panel-input" name="sku" value="${editorEscape(config.sku||'SKU-'+id)}" required></label><label class="field-label">Estoque<input class="panel-input" name="stock" type="number" min="0" step="1" value="${config.stock??8}" required></label></div><p class="catalog-help">Sem seletor de variação na página ou na sacola. Características fixas podem fazer parte da descrição.</p>`;
    if(type==='variable')fields.innerHTML=`<h3>Atributos configuráveis</h3><div id="attribute-rows">${attrRows()}</div><div class="editor-actions"><button class="btn secondary" type="button" data-editor-action="add-attribute">Adicionar atributo</button><button class="btn secondary" type="button" data-editor-action="generate">Gerar combinações</button></div><p class="catalog-help">Configure quaisquer atributos necessários. Cada combinação tem SKU, preço, estoque e disponibilidade próprios. Limite técnico demonstrativo: 100 combinações.</p><div id="variants-table">${variants.length?rows():''}</div>`;
    if(type==='kit')fields.innerHTML=`<label class="field-label">Modalidade do kit<select class="panel-input" name="kitMode"><option value="closed" ${config.kitMode==='closed'?'selected':''}>Kit fechado — todos os itens</option><option value="open" ${config.kitMode==='open'?'selected':''}>Kit aberto — mínimo 2 produtos diferentes</option></select></label><p class="catalog-help">Selecione pelo menos 2 produtos da própria loja. O cliente escolhe as variações de cada componente. O preço inicial é a soma dos itens escolhidos; o estoque vem dos componentes.</p><div class="component-picker">${componentPool.map(p=>{const c=config.components?.find(c=>c.productId===p.id);return `<div><label><input type="checkbox" name="component" value="${p.id}" ${c?'checked':''}>${p.name} <small>${TYPE_LABELS[p.type]}</small></label><label>Unidades por kit<input class="panel-input" type="number" min="1" step="1" name="componentQty-${p.id}" value="${c?.qty||1}" aria-label="Quantidade de ${p.name} por kit"></label></div>`}).join('')}</div>`;
    if(type==='virtual')fields.innerHTML=`<h3>Arquivo para download</h3><label class="field-label">Arquivo digital<input class="panel-input" name="digitalFile" type="file" accept=".pdf,.epub,.png,.jpg,.jpeg,.webp"></label><p id="digital-metadata" class="catalog-help">${digital?editorEscape(digital.fileName)+' · '+digital.format:'PDF, EPUB, PNG, JPEG ou WEBP. Limite demonstrativo de 20 MB. Sem vídeos, cursos, HTML ou executáveis.'}</p><label class="field-label">Condições de uso / licença<textarea class="panel-input" name="license" required maxlength="1000">${editorEscape(config.digital?.license||'Uso pessoal. Não redistribuir.')}</textarea></label><label class="editor-attestation"><input type="checkbox" name="noCourse" ${config.digital?'checked':''} required>Este produto é um arquivo digital e não é um curso ou aula em vídeo.</label><p class="catalog-help">Sem frete ou despacho físico. Na operação real, entrega privada após pagamento confirmado. Aqui apenas os metadados são salvos.</p>`;
  }
  function list(){const drafts=readProductDrafts().filter(p=>p.store===sellerContext());document.querySelector('#product-drafts-list').innerHTML=drafts.length?drafts.map(p=>`<div class="draft-row"><div><b>${editorEscape(p.name)}</b><small>${TYPE_LABELS[p.type]}${p.type==='kit'?' · '+(p.kitMode==='open'?'Aberto':'Fechado'):''} · ${({pending:'Em análise',approved:'Aprovado',rejected:'Rejeitado',draft:'Rascunho'}[p.status]||p.status)}</small></div><button type="button" class="text-link" data-edit-draft="${p.id}">Editar configuração →</button></div>`).join(''):'<p>Nenhum rascunho salvo neste navegador.</p>';}
  document.querySelector('#new-product').onclick=()=>{original=null;id=Date.now();type='simple';attributes=[];variants=[];digital=null;f.reset();mediaEditor?.set([]);draw();feedback.textContent='Novo cadastro iniciado.'};
  document.querySelectorAll('[data-editor-type]').forEach(b=>b.onclick=()=>{type=b.dataset.editorType;attributes=[];variants=[];digital=null;feedback.textContent='';draw()});
  fields.addEventListener('input',e=>{if(e.target.dataset.attrName!==undefined){attributes[Number(e.target.dataset.attrName)].name=e.target.value;variants=[];document.querySelector('#variants-table').innerHTML=''}if(e.target.dataset.attrValues!==undefined){attributes[Number(e.target.dataset.attrValues)].values=e.target.value.split(',').map(v=>v.trim()).filter(Boolean);variants=[];document.querySelector('#variants-table').innerHTML=''}if(e.target.dataset.variant!==undefined){const v=variants[Number(e.target.dataset.variant)],key=e.target.dataset.field;v[key]=key==='active'?e.target.checked:key==='priceCents'?Math.round(Number(e.target.value)*100):key==='stock'?Number(e.target.value):e.target.value;}});
  fields.addEventListener('click',e=>{const action=e.target.dataset.editorAction;if(action==='add-attribute'){attributes.push({name:'',values:[]});document.querySelector('#attribute-rows').innerHTML=attrRows();variants=[];document.querySelector('#variants-table').innerHTML=''}if(e.target.dataset.removeAttr!==undefined){attributes.splice(Number(e.target.dataset.removeAttr),1);variants=[];draw()}if(action==='generate'){if(!attributes.length||attributes.some(a=>!a.name.trim()||!a.values.length)||new Set(attributes.map(a=>a.name.toLowerCase())).size!==attributes.length){feedback.textContent='Preencha atributos distintos e suas opções.';return}const count=attributes.reduce((n,a)=>n*a.values.length,1);if(count>100){feedback.textContent='O limite demonstrativo é de 100 combinações.';return}variants=makeVariants(id,attributes,Number(f.elements.price.value));document.querySelector('#variants-table').innerHTML=rows();feedback.textContent=`${variants.length} combinações geradas.`;}});
  fields.addEventListener('change',e=>{if(e.target.name==='digitalFile'){const file=e.target.files[0];digital=null;if(!file)return;const ext=file.name.split('.').at(-1).toUpperCase(),format=ext==='JPG'?'JPEG':ext;if(!['PDF','EPUB','PNG','JPEG','WEBP'].includes(format)||file.size>20*1024*1024||file.type.startsWith('video/')){e.target.value='';feedback.textContent='Arquivo não permitido. Use os formatos indicados, até 20 MB. Vídeos e cursos não são aceitos.';return}digital={fileName:file.name,fileSize:file.size,format};document.querySelector('#digital-metadata').textContent=`${file.name} · ${format} · ${Math.ceil(file.size/1024)} KB. Apenas metadados; sem upload.`;}});
  f.onsubmit=e=>{e.preventDefault();const data=new FormData(f);const p={id,videoUrl:String(data.get('videoUrl')||original?.videoUrl||''),firstMedia:String(data.get('firstMedia')||'image'),existingCatalog:!!original?.existingCatalog,description:String(data.get('description')||''),category:String(data.get('category')||''),image:String(data.get('image')||original?.image||''),store:sellerContext(),name:data.get('name').trim(),type,priceCents:Math.round(Number(data.get('price'))*100),sku:data.get('sku')||'ML-'+id,stock:Number(data.get('stock')||0),attributes:structuredClone(attributes),variants:structuredClone(variants),kitMode:data.get('kitMode'),components:data.getAll('component').map(id=>({productId:Number(id),qty:Number(data.get('componentQty-'+id))})),digital:type==='virtual'?{...digital,license:data.get('license')}:null,status:e.submitter?.name==='submitReview'?'pending':'draft'};try{if(mediaEditor){p.media=mediaEditor.get();if(!p.media.some(m=>m.type==='image'))throw Error('Inclua ao menos uma foto para representar o produto.');p.image=p.media.find(m=>m.type==='image').src;p.videoUrl=p.media.find(m=>m.type==='video')?.src||'';p.firstMedia=p.media[0].type;}if(p.videoUrl&&!validProductVideo(p.videoUrl))throw Error('Informe um vídeo MP4 ou WebM em HTTPS.');if(p.firstMedia==='video'&&!p.videoUrl)throw Error('Informe o vídeo antes de escolhê-lo como primeira mídia.');if(data.get('image')&&!String(data.get('image')).startsWith('https://'))throw Error('Use uma imagem HTTPS.');validateProductConfig(p,componentPool);const persistent=saveProductDraft(p);feedback.textContent=`${p.status==='pending'?'Enviado para a fila demonstrativa de aprovação.':'Rascunho salvo.'} ${persistent?'Dados locais neste navegador.':'Armazenamento indisponível: mantido apenas nesta sessão.'} Conteúdo editorial aguarda aprovação; preço e estoque de produtos cadastrados são atualizados localmente.`;list();}catch(err){feedback.textContent=err.message}};
  document.querySelector('#product-drafts-list').onclick=e=>{const b=e.target.closest('[data-edit-draft]');if(!b)return;const p=sellerProducts().find(p=>p.id===Number(b.dataset.editDraft));if(!p)return;original=p;id=p.id;type=p.type;attributes=structuredClone(p.attributes||[]);variants=structuredClone(p.variants||[]);digital=p.digital;f.elements.name.value=p.name;f.elements.price.value=p.priceCents/100;f.elements.description.value=p.description||'';f.elements.category.value=p.category||'';f.elements.image.value=p.image?.startsWith('https://')?p.image:'';if(f.elements.videoUrl)f.elements.videoUrl.value=p.videoUrl?.startsWith('https://')?p.videoUrl:'';if(f.elements.firstMedia)f.elements.firstMedia.value=p.firstMedia||'image';mediaEditor?.set(orderedProductMedia(p));draw(p);feedback.textContent='Rascunho carregado para edição.';f.scrollIntoView({block:'start'})};draw();list();if(editId!==null){const p=sellerProducts().find(p=>p.id===editId);if(p){document.querySelector('#product-drafts-list').onclick({target:{closest:()=>({dataset:{editDraft:String(editId)}})}});document.querySelectorAll('[data-editor-type]').forEach(b=>b.disabled=!!p.existingCatalog);}}document.querySelector('#new-product').hidden=editId!==null;
}

export function pendingProductMarkup(){const pending=readProductDrafts().filter(p=>p.status==='pending');return '<section class="portal-panel"><h2>Produtos enviados neste navegador</h2>'+ (pending.length?pending.map(p=>'<div class="draft-row"><div><b>'+editorEscape(p.name)+'</b><small>'+editorEscape(TYPE_LABELS[p.type])+' · Casa Aurora · Em análise</small></div></div>').join(''):'<p>Nenhum cadastro local aguardando aprovação.</p>')+'</section>'}

export function sellerProducts(){const drafts=readProductDrafts().filter(p=>p.store===sellerContext()),base=marketplaceCatalog().filter(p=>p.store===sellerContext()).map(p=>({...p,existingCatalog:true,status:'published'}));return base.map(p=>({...p,...drafts.find(d=>d.id===p.id)})).concat(drafts.filter(d=>!base.some(p=>p.id===d.id)));}
export function sellerProductListMarkup(){return '<section class="portal-panel"><div class="editor-heading"><div><h2>Meus produtos</h2><p>Consulte e edite os produtos desta loja.</p></div><a class="btn" href="#seller/novo-produto">Cadastrar produto</a></div><label class="field-label">Buscar por nome ou SKU<input id="seller-product-search" class="panel-input" type="search"></label><div class="portal-table"><table><thead><tr><th>Produto</th><th>SKU</th><th>Tipo</th><th>Preço</th><th>Estoque</th><th>Situação editorial</th><th>Ação</th></tr></thead><tbody>'+sellerProducts().map(p=>'<tr data-product-search="'+editorEscape((p.name+' '+p.sku).toLowerCase())+'"><td>'+ (p.image?'<img src="'+editorEscape(p.image)+'" alt="" width="48" height="48" style="object-fit:cover;border-radius:8px;vertical-align:middle;margin-right:10px">':'')+editorEscape(p.name)+'</td><td>'+editorEscape(p.sku)+'</td><td>'+TYPE_LABELS[p.type]+'</td><td>'+new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(p.priceCents/100)+'</td><td>'+(p.type==='variable'?p.variants.reduce((n,v)=>n+v.stock,0):p.type==='simple'?p.stock:'—')+'</td><td>'+({published:'Publicado',draft:'Rascunho',pending:'Em análise',approved:'Aprovado',rejected:'Revisar'}[p.status]||'Rascunho')+'</td><td><a class="text-link" href="#seller/editar-produto/'+p.id+'">Editar</a></td></tr>').join('')+'</tbody></table></div><p id="seller-product-empty" hidden>Nenhum produto encontrado.</p></section>';}
export function mountSellerProductList(){const field=document.querySelector('#seller-product-search');field.oninput=()=>{let count=0;document.querySelectorAll('[data-product-search]').forEach(row=>{row.hidden=!row.dataset.productSearch.includes(field.value.trim().toLowerCase());if(!row.hidden)count++;});document.querySelector('#seller-product-empty').hidden=count>0;};}


